<?php
namespace App\Http\Controllers;
use App\Models\{Evaluation,Feedback,TeachingMaterial,TeachingReport,Timetable,User,PerformanceReport};
class DashboardController extends Controller { public function show(){ $u=request()->user(); $data=['users'=>User::count(),'teachers'=>User::teachers()->count(),'activeTeachers'=>User::teachers()->active()->count(),'supervisors'=>User::supervisors()->count(),'managers'=>User::schoolManagers()->count(),'reports'=>TeachingReport::count(),'materials'=>TeachingMaterial::count(),'averageScore'=>round((float)Evaluation::avg('score'),2),'recentReports'=>TeachingReport::with('teacher')->latest('submitted_at')->limit(5)->get(),'recentEvaluations'=>Evaluation::with('teacher')->latest('evaluated_at')->limit(5)->get()]; if($u->role==='teacher'){$data+=['myTimetables'=>$u->timetables()->orderByRaw("CASE day WHEN 'Sun' THEN 1 WHEN 'Mon' THEN 2 WHEN 'Tue' THEN 3 WHEN 'Wed' THEN 4 ELSE 5 END")->get(),'myReports'=>$u->teachingReports()->latest('submitted_at')->limit(5)->get(),'myFeedback'=>$u->feedbackReceived()->latest('submitted_at')->first(),'myEvaluation'=>$u->evaluationsReceived()->latest('evaluated_at')->first()];} if($u->role==='supervisor'){$data+=['assigned'=>$u->supervisedTeachers()->active()->get(),'assignedReports'=>TeachingReport::whereIn('teacher_id',$u->supervisedTeachers()->pluck('id'))->latest('submitted_at')->limit(8)->get()];} return view('dashboard',compact('data','u')); } }
